mapper.insert:

    SELECT PAYMENT_SEQ.NEXTVAL FROM DUAL

INSERT INTO PAYMENT (
PAYMENT_ID, REQUEST_ID, FIXER_NO, TOTAL_AMOUNT, PAYMENT_METHOD, CREATED_AT
) VALUES (
#{paymentId}, #{requestId}, #{fixerNo}, #{totalAmount}, #{paymentMethod}, SYSTIMESTAMP
)

INSERT INTO PAYMENT_DETAIL (
    DETAIL_ID, PAYMENT_ID, ITEM_CODE, ITEM_NAME, QUANTITY, UNIT_PRICE
) VALUES (
             PAYMENT_DETAIL_SEQ.NEXTVAL, #{paymentId}, #{itemCode}, #{itemName}, #{quantity}, #{unitPrice}
         )
